module legacy_floats;
fn factory(offset:i64)->fn(i64)->i64{return fn(value:i64)->i64{return value+offset;};}
fn choose(value:result<i64>)->i64{return match value{ok(n) if n>0=>factory(2)(n),_=>0};}
fn main()->unit!{io}{print(choose(ok(40)));}
test fn cases()->unit{assert(choose(ok(40))==42);}

